def largest_num(nums):
    largest = nums[0]
    for n in nums:
        if n > largest:
            largest = n
    return largest

import math

def volume_cylinder(radius, height):
    return math.pi * radius ** 2 * height

def min_Abs_Diff(arr):
    arr = sorted(arr)
    return min(arr[i+1] - arr[i] for i in range(len(arr)-1))
